run_approvals.py<pre><code>import asyncio
import json

from kedi.lang import compile_program, parse_program

from backend import BackendRequest, Reply, ToolCall
from chat_adapter import ChatAdapter
from native_approvals import NativeApprovalAdapter

FENCE = "`" * 3
SOURCE = f"""
{FENCE}
from kedi import ApprovalDecision

def approve(request):
    if request.arguments["path"].startswith("reports/"):
        return ApprovalDecision.allow()
    return ApprovalDecision.edit({{"path": "reports/" + request.arguments["path"]}})
{FENCE}

@write_report(path: str) -&gt; str:
  ###
  Write the report to a path.
  ###
  &gt; tool:
    risk: mutating
  = `"wrote " + path`

&gt; approval: `approve`
&gt; use: write_report
[answer] &lt;&lt; Write the report to notes.txt.
= &lt;answer&gt;
"""


class Script:
    async def complete(self, request: BackendRequest) -&gt; Reply:
        results = [json.loads(m["content"]) for m in request.messages if m["role"] == "tool"]
        if not results:
            return Reply(tool_calls=(ToolCall("c1", "write_report", {"path": "notes.txt"}),))
        return Reply(text=results[0].get("result") or results[0]["error"])


def run(source: str, adapter_type: type[ChatAdapter]) -&gt; str:
    runtime = compile_program(parse_program(source), adapter=adapter_type(Script(), model="m1"))
    try:
        return runtime.run_main()
    finally:
        asyncio.run(runtime.aclose())


for adapter_type in (ChatAdapter, NativeApprovalAdapter):
    assert run(SOURCE, adapter_type) == "wrote reports/notes.txt", adapter_type
    denied = run(SOURCE.replace("&gt; approval: `approve`", "&gt; approval: deny"), adapter_type)
    assert "was denied" in denied, (adapter_type, denied)
</code></pre> <p>Both adapters apply the same policy: the handler's edit reaches the tool, and <code>&gt; approval: deny</code> returns a denial to the model.</p>

run_capabilities.py<pre><code>import asyncio
from dataclasses import replace

from kedi.agent_adapter import MissingAdapterCapabilityError
from kedi.lang import compile_program, parse_program

from backend import BackendRequest, Reply
from chat_adapter import ChatAdapter


class Echo:
    async def complete(self, request: BackendRequest) -&gt; Reply:
        return Reply(text="ok")


def run(source: str, adapter: ChatAdapter) -&gt; object:
    runtime = compile_program(parse_program(source), adapter=adapter)
    try:
        return runtime.run_main()
    finally:
        asyncio.run(runtime.aclose())


SOURCE = "&gt; requires:\n    tool_registration\n    stream_events\n[a] &lt;&lt; Hi.\n= &lt;a&gt;\n"

try:
    run(SOURCE, ChatAdapter(Echo(), model="m1"))
except MissingAdapterCapabilityError as error:
    assert error.requirement == "stream_events"
    assert "does not satisfy required capability 'stream_events'" in str(error)
else:
    raise AssertionError("stream_events is unknown, so it must fail")


class NegotiatingAdapter(ChatAdapter):
    capabilities = replace(
        ChatAdapter.capabilities, negotiated_capabilities=frozenset({"stream_events"})
    )


assert run(SOURCE, NegotiatingAdapter(Echo(), model="m1")) == "ok"
</code></pre>

run_errors.py<pre><code>import asyncio
import json
from collections.abc import Callable

from kedi.errors import KediExecutionError
from kedi.lang import compile_program, parse_program

from backend import BackendRequest, Reply, ToolCall
from chat_adapter import ChatAdapter


class Scripted:
    def __init__(self, answer: Callable[[BackendRequest], Reply]) -&gt; None:
        self.answer = answer
        self.requests: list[BackendRequest] = []

    async def complete(self, request: BackendRequest) -&gt; Reply:
        self.requests.append(request)
        return self.answer(request)


def run(source: str, backend) -&gt; object:
    runtime = compile_program(parse_program(source), adapter=ChatAdapter(backend, model="m1"))
    try:
        return runtime.run_main()
    finally:
        asyncio.run(runtime.aclose())


def tool_program(body: str, approval: str = "allow", risk: str = "read_only") -&gt; str:
    return f"""
@lookup(city: str) -&gt; str:
  ###
  Look up a city.
  ###
  &gt; tool:
    risk: {risk}
  = `{body}`

&gt; approval: {approval}
&gt; use: lookup
[answer] &lt;&lt; Look up Atlantis.
= &lt;answer&gt;
"""


def call_then_echo(request: BackendRequest) -&gt; Reply:
    results = [json.loads(m["content"]) for m in request.messages if m["role"] == "tool"]
    if not results:
        return Reply(tool_calls=(ToolCall("c1", "lookup", {"city": "Atlantis"}),))
    return Reply(text=results[0]["error"])
</code></pre> <p>A correctable failure reaches the model with Kedi's message:</p> run_errors.py<pre><code>answer = run(tool_program("(_ for _ in ()).throw(ValueError('unknown city'))"), Scripted(call_then_echo))
assert answer.startswith("Tool lookup failed: ValueError: unknown city."), answer
</code></pre> <p>A denial reaches the model, and the run continues:</p> run_errors.py<pre><code>answer = run(tool_program("'ok'", approval="deny", risk="mutating"), Scripted(call_then_echo))
assert "was denied" in answer, answer
</code></pre> <p>Any other failure ends the call:</p> run_errors.py<pre><code>try:
    run(tool_program("(_ for _ in ()).throw(RuntimeError('database is down'))"), Scripted(call_then_echo))
except KediExecutionError as error:
    assert "database is down" in str(error)
else:
    raise AssertionError("an unclassified tool failure must end the call")
</code></pre> <p>A rate limit is retried; a bad request is not:</p> run_errors.py<pre><code>class ProviderError(Exception):
    def __init__(self, status_code: int) -&gt; None:
        super().__init__(f"HTTP {status_code}")
        self.status_code = status_code
        self.response = type("Response", (), {"headers": {"retry-after": "0"}})()


class Flaky:
    def __init__(self, status_code: int) -&gt; None:
        self.status_code = status_code
        self.calls = 0

    async def complete(self, request: BackendRequest) -&gt; Reply:
        self.calls += 1
        if self.calls == 1:
            raise ProviderError(self.status_code)
        return Reply(text="ok")


flaky = Flaky(429)
assert run("[answer] &lt;&lt; Say ok.\n= &lt;answer&gt;\n", flaky) == "ok"
assert flaky.calls == 2

rejected = Flaky(400)
try:
    run("[answer] &lt;&lt; Say ok.\n= &lt;answer&gt;\n", rejected)
except KediExecutionError as error:
    assert isinstance(error.original, ProviderError)
else:
    raise AssertionError("a 400 must not be retried")
assert rejected.calls == 1
</code></pre>

chat_adapter.py<pre><code>    def default_model(self) -&gt; str | None:
        return self._model

    @property
    def active_profile(self) -&gt; AgentProfile:
        stack = self._profiles.get()
        return stack[-1] if stack else AgentProfile.empty()

    @contextmanager
    def profile_override(self, profile: AgentProfile) -&gt; Generator[None, None, None]:
        unsupported = [
            name
            for name, present in (
                ("effort", profile.effort is not None),
                ("mcp", bool(profile.mcp_servers)),
            )
            if present
        ]
        unsupported += sorted(
            set(profile.settings) - KEDI_RUNTIME_SETTING_KEYS - self.capabilities.settings
        )
        if unsupported:
            raise AgentProfileOverrideUnsupported(
                f"{self.shortname} does not support profile fields: {', '.join(unsupported)}"
            )
        token = self._profiles.set((*self._profiles.get(), profile))
        try:
            yield
        finally:
            self._profiles.reset(token)
</code></pre> <p>Kedi enters <code>profile_override(profile)</code> around every call. Once an adapter implements it, Kedi no longer rejects profile fields on the adapter's behalf, so the adapter must refuse what it cannot honor. Settings named in <code>KEDI_RUNTIME_SETTING_KEYS</code> (<code>context_limit</code>, <code>media_limit</code>, <code>request_retries</code>, <code>tool_reason</code>, <code>voice</code>) belong to Kedi and are never an error; see Profiles, Models, and Settings. The profile's <code>&gt; instructions:</code> need no handling here: Kedi already renders them into the <code>instructions</code> argument. A direct or native call made inside <code>profile_override</code> may pass none; send <code>profile.call_instructions(instructions)</code>, which falls back to the profile's instructions for <code>None</code> and keeps an explicit empty string.</p>

chat_adapter.py<pre><code>    @contextmanager
    def tool_scope(self, tools: Sequence[object] = ()) -&gt; Generator[None, None, None]:
        token = self._tools.set(tuple(tool for tool in tools if isinstance(tool, ToolSpec)))
        try:
            yield
        finally:
            self._tools.reset(token)

    def register_tool(self, tool: ToolSpec) -&gt; None:
        self._tools.set((*self._tools.get(), tool))

    async def _execute(self, tools: dict[str, ToolSpec], call: ToolCall) -&gt; str:
        tool = tools.get(call.name)
        if tool is None:
            return json.dumps({"ok": False, "error": f"Unknown tool {call.name!r}"})
        try:
            result = tool.fn(**validate_tool_arguments(tool, call.arguments))
            if inspect.isawaitable(result):
                result = await result
        except (ToolApprovalDenied, HookDeniedError) as exc:
            return json.dumps({"ok": False, "error": exc.message})
        except Exception as exc:
            message = correctable_tool_error(tool, exc)
            if message is None:
                raise
            return json.dumps({"ok": False, "error": message})
        return json.dumps({"ok": True, "result": to_jsonable_python(result, fallback=str)})

    @staticmethod
    def _declaration(tool: ToolSpec) -&gt; dict[str, Any]:
        return {
            "name": tool.name,
            "description": tool.description or "",
            "parameters": tool.json_schema or {"type": "object", "properties": {}},
        }
</code></pre> <p><code>tool.fn</code> is already wrapped by Kedi. Calling it applies approval policy, required-tool tracking, artifact admission, and telemetry. Some Kedi tools are coroutines (subagent delegation is one), so always await an awaitable result.</p> <p>Failures take one of three paths, the same ones Kedi's built-in adapters use:</p> <ul> <li>a denial (<code>ToolApprovalDenied</code>, or <code>HookDeniedError</code> from a <code>pre_tool_use</code>   hook) goes back to the model as a failed result; the run continues;</li> <li>an error that <code>correctable_tool_error</code> classifies as correctable goes back   to the model with Kedi's message;</li> <li>anything else, including budget exhaustion and cancellation, propagates and   ends the run.</li> </ul> <p>See Errors, Retries, and Cancellation.</p>

chat_adapter.py<pre><code>    async def _run(
        self,
        *,
        prompt: str,
        instructions: str | None,
        output_schema: dict[str, Any] | None,
        history: Sequence[dict[str, Any]] = (),
        max_requests: int | None = None,
    ) -&gt; tuple[Reply, list[dict[str, Any]]]:
        messages = [*history, {"role": "user", "content": prompt}]
        tools = {tool.name: tool for tool in self._tools.get()}
        steps = self._max_steps if max_requests is None else min(self._max_steps, max_requests)
        for _ in range(steps):
            reply = await self._complete(
                BackendRequest(
                    model=self.active_profile.model or self._model,
                    instructions=instructions,
                    messages=list(messages),
                    tools=[self._declaration(tool) for tool in tools.values()],
                    output_schema=output_schema,
                    temperature=self.active_profile.settings.get("temperature"),
                )
            )
            report_invocation(
                InvocationUsage(
                    requests=1,
                    tool_calls=len(reply.tool_calls),
                    input_tokens=reply.input_tokens,
                    output_tokens=reply.output_tokens,
                    total_tokens=reply.input_tokens + reply.output_tokens,
                )
            )
            if not reply.tool_calls:
                content = reply.text if output_schema is None else json.dumps(reply.data)
                messages.append({"role": "assistant", "content": content})
                return reply, messages
            messages.append(
                {
                    "role": "assistant",
                    "tool_calls": [
                        {"id": call.id, "name": call.name, "arguments": call.arguments}
                        for call in reply.tool_calls
                    ],
                }
            )
            for call in reply.tool_calls:
                content = await self._execute(tools, call)
                messages.append({"role": "tool", "tool_call_id": call.id, "content": content})
        raise RuntimeError(f"{self.shortname} stopped after {steps} model requests")

    async def _complete(self, request: BackendRequest) -&gt; Reply:
        retries = request_retry_limit(self.active_profile.settings, self._request_retries)
        attempt = 0
        while True:
            admit_run_operation("request")
            try:
                return await self._backend.complete(request)
            except Exception as error:
                attempt += 1
                retry = await wait_for_request_retry(error, attempt=attempt, retries=retries)
                if not retry:
                    raise

    async def invoke(self, *, prompt: str, instructions: str | None = None, **_: Any) -&gt; str:
        reply, _messages = await self._run(
            prompt=prompt, instructions=instructions, output_schema=None
        )
        if reply.text is None:
            raise RuntimeError("The backend returned no text")
        return reply.text

    async def produce(
        self,
        *,
        template: str,
        output_schema: dict[str, Any] | None = None,
        output_type: Any = None,
        instructions: str | None = None,
        **_: Any,
    ) -&gt; Any:
        if output_schema is not None:
            schema = build_output_model(output_schema).model_json_schema()
        else:
            schema = TypeAdapter(output_type).json_schema()
        reply, _messages = await self._run(
            prompt=template, instructions=instructions, output_schema=schema
        )
        return reply.data

    def invoke_sync(self, **kwargs: Any) -&gt; str:
        return run_sync(self.invoke(**kwargs))

    def produce_sync(self, **kwargs: Any) -&gt; Any:
        return run_sync(self.produce(**kwargs))
</code></pre> <p>The rules that matter:</p> <ul> <li>One loop. The synchronous entry points use <code>run_sync</code> from   <code>kedi.agent_adapter.execution</code>, never <code>asyncio.run</code>. Kedi runs all   overlapping model work on one shared event loop, and background subagents   started by a tool call keep running on it after the call returns. A private   loop would close under them. See Concurrency and Event Loops.</li> <li>Kedi's text, unchanged. <code>instructions</code> is the system message, the prompt   is the user message, and the JSON Schema comes from <code>build_output_model</code>, so   the field descriptions Kedi adds reach the model.</li> <li>Usage after every request. <code>report_invocation</code> feeds subagent usage   limits, request-size reservations, telemetry, and checkpoint usage events.   A subagent limit that is exceeded raises from inside <code>report_invocation</code>;   let that exception propagate. Run budgets (<code>&gt; budget:</code>) need one more call   before each request: <code>admit_run_operation("request")</code>, which <code>_complete</code>   calls before every attempt; see Budgets and Usage.</li> <li>Kedi validates. <code>produce</code> returns the decoded value. Kedi checks it   against the requested type, converts it, and fails the call if a field is   missing.</li> </ul>

subagent_adapter.py<pre><code>    @staticmethod
    def subagent_run_kwargs(limits: SubagentUsageLimits) -&gt; Mapping[str, Any]:
        return {"max_requests": limits.request_limit}
</code></pre> <p><code>SubagentUsageLimits</code> carries the remaining budget of the logical child task: <code>request_limit</code> (default 8), <code>tool_calls_limit</code> (default 16), and optional <code>input_tokens_limit</code>, <code>output_tokens_limit</code>, and <code>total_tokens_limit</code>. The mapping you return is passed to <code>invoke</code> / <code>produce_subagent</code> as keyword arguments, so translate the limits into whatever your backend understands.</p> <p>Kedi enforces the limits from the usage you report with <code>report_invocation</code>: a report that exceeds a limit raises <code>KediExecutionError: Subagent request limit 8 exceeded: observed 9</code> inside <code>report_invocation</code>, and the child fails. A continuation whose budget is already spent fails before the adapter is called, with <code>Subagent request_limit exhausted; task was not restarted</code>. Passing the limits to the backend stops the run earlier and cheaper, but reporting usage is what makes the limits hold.</p> <p>Token limits hold only when the tokens are measured. On an adapter without <code>supports_token_usage</code>, a child with token limits fails before it runs. A report whose count a limit depends on is <code>None</code> fails the child: <code>Subagent input token limit 20000 cannot be enforced: the backend did not report input tokens</code>.</p>

run_subagents.py<pre><code>import asyncio
import json
from collections.abc import Callable

from kedi.lang import compile_program, parse_program

from backend import BackendRequest, Reply, ToolCall
from subagent_adapter import SubagentChatAdapter

PROFILES = """
~Status(order: str, state: str)

&gt; profile: worker:
    ###
    Looks up the status of one order.
    ###
    &gt; instructions: Report the status of the order you are given.
    {output}

&gt; profile: coordinator:
    &gt; subagent: worker

&gt; use: coordinator
[answer] &lt;&lt; Find out the status of order O-1.
= &lt;answer&gt;
"""


class ScriptedBackend:
    def __init__(self, answer: Callable[[BackendRequest], Reply]) -&gt; None:
        self.answer = answer
        self.requests: list[BackendRequest] = []

    async def complete(self, request: BackendRequest) -&gt; Reply:
        self.requests.append(request)
        return self.answer(request)


def is_parent(request: BackendRequest) -&gt; bool:
    return any(tool["name"] == "delegate_task" for tool in request.tools)


def tool_results(request: BackendRequest) -&gt; list[dict]:
    return [json.loads(m["content"]) for m in request.messages if m["role"] == "tool"]


def run(source: str, answer: Callable[[BackendRequest], Reply]) -&gt; tuple[object, ScriptedBackend]:
    backend = ScriptedBackend(answer)
    adapter = SubagentChatAdapter(backend, model="m1")
    runtime = compile_program(parse_program(source), adapter=adapter)
    try:
        return runtime.run_main(), backend
    finally:
        asyncio.run(runtime.aclose())
</code></pre> <p>A text child. The parent's model calls <code>delegate_task</code>; the child's model answers with text, which comes back as <code>task_summary</code>:</p> run_subagents.py<pre><code>def text_child(request: BackendRequest) -&gt; Reply:
    if not is_parent(request):
        return Reply(text="O-1 was delivered on Monday.")
    results = tool_results(request)
    if not results:
        return Reply(
            tool_calls=(
                ToolCall("p1", "delegate_task", {"subagent": "worker", "task": "Status of O-1?"}),
            )
        )
    return Reply(text=results[0]["result"]["task_summary"])


value, backend = run(PROFILES.format(output=""), text_child)
assert value == "O-1 was delivered on Monday."
child = next(r for r in backend.requests if not is_parent(r))
assert "Report the status" in (child.instructions or "")
assert child.tools == [] or all(t["name"] != "delegate_task" for t in child.tools)
</code></pre> <p>A structured child from the profile's <code>&gt; output:</code> type, whose first answer forgets the wrapper and is corrected with Kedi's feedback:</p> run_subagents.py<pre><code>def structured_child(request: BackendRequest) -&gt; Reply:
    if not is_parent(request):
        assert request.output_schema is not None
        assert request.output_schema["title"] == "KediSubagentResult"
        if len(request.messages) == 1:
            return Reply(data={"order": "O-1", "state": "delivered"})
        assert "task_summary and final_result" in request.messages[-1]["content"]
        return Reply(
            data={
                "task_summary": "Looked up O-1.",
                "final_result": {"order": "O-1", "state": "delivered"},
            }
        )
    results = tool_results(request)
    if not results:
        return Reply(
            tool_calls=(
                ToolCall("p1", "delegate_task", {"subagent": "worker", "task": "Status of O-1?"}),
            )
        )
    return Reply(text=results[0]["result"]["final_result"]["state"])


value, backend = run(PROFILES.format(output="&gt; output: Status"), structured_child)
assert value == "delivered"
assert sum(not is_parent(r) for r in backend.requests) == 2
</code></pre> <p>A continuation with native resume. The second child run starts from the messages the first run saved:</p> run_subagents.py<pre><code>def continued_child(request: BackendRequest) -&gt; Reply:
    if not is_parent(request):
        users = [m["content"] for m in request.messages if m["role"] == "user"]
        assert not any("verified prior conversation" in text for text in users)
        return Reply(text=f"answered {len(users)} task(s)")
    results = tool_results(request)
    if not results:
        return Reply(
            tool_calls=(
                ToolCall("p1", "delegate_task", {"subagent": "worker", "task": "Status of O-1?"}),
            )
        )
    if len(results) == 1:
        run_id = results[0]["result"]["run_id"]
        return Reply(
            tool_calls=(
                ToolCall("p2", "continue_subagent", {"run_id": run_id, "task": "And O-2?"}),
            )
        )
    return Reply(text=results[1]["result"]["task_summary"])


value, _backend = run(PROFILES.format(output=""), continued_child)
assert value == "answered 2 task(s)"
</code></pre> <p>A background child. <code>delegate_task</code> returns a running handle at once; <code>wait_subagent</code> returns the result:</p> run_subagents.py<pre><code>def background_child(request: BackendRequest) -&gt; Reply:
    if not is_parent(request):
        return Reply(text="O-1 was delivered.")
    results = tool_results(request)
    if not results:
        arguments = {"subagent": "worker", "task": "Status of O-1?", "background": True}
        return Reply(tool_calls=(ToolCall("p1", "delegate_task", arguments),))
    if len(results) == 1:
        handle = results[0]["result"]
        assert handle["status"] in {"running", "completed"}
        return Reply(
            tool_calls=(ToolCall("p2", "wait_subagent", {"run_id": handle["run_id"]}),)
        )
    return Reply(text=results[1]["result"]["task_summary"])


value, _backend = run(PROFILES.format(output=""), background_child)
assert value == "O-1 was delivered."
</code></pre> <p>A parent's <code>deny</code> binds a child whose own profile says <code>allow</code>:</p> run_subagents.py<pre><code>GUARDED = """
@cancel_order(order: str) -&gt; str:
  ###
  Cancel an order.
  ###
  &gt; tool:
    risk: mutating
  = `"cancelled " + order`

&gt; profile: worker:
    ###
    Handles orders.
    ###
    &gt; approval: allow
    &gt; use: cancel_order

&gt; profile: coordinator:
    &gt; approval: deny
    &gt; subagent: worker

&gt; use: coordinator
[answer] &lt;&lt; Cancel order O-1.
= &lt;answer&gt;
"""


def guarded_child(request: BackendRequest) -&gt; Reply:
    results = tool_results(request)
    if not is_parent(request):
        if not results:
            return Reply(tool_calls=(ToolCall("c1", "cancel_order", {"order": "O-1"}),))
        return Reply(text=results[0].get("error") or results[0]["result"])
    if not results:
        arguments = {"subagent": "worker", "task": "Cancel O-1."}
        return Reply(tool_calls=(ToolCall("p1", "delegate_task", arguments),))
    return Reply(text=results[0]["result"]["task_summary"])


value, _backend = run(GUARDED, guarded_child)
assert "was denied" in value, value
</code></pre>
